// Clean up the form submission and catch obvious spam before spending an AI call.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json || {};
  const pick = (...keys) => { for (const k of keys) if (b[k] !== undefined && String(b[k]).trim() !== '') return String(b[k]).trim(); return ''; };
  const name = pick('name', 'full_name', 'fullName').slice(0, 120);
  const email = pick('email', 'Email').toLowerCase().slice(0, 160);
  const phone = pick('phone', 'tel', 'mobile').slice(0, 40);
  const message = pick('message', 'enquiry', 'comments').slice(0, 3000);
  const honeypot = pick('website', 'company_website');           // hidden field real people leave empty
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
  const links = (message.match(/https?:\/\//g) || []).length;
  const valid = emailOk && message.length >= 5 && !honeypot && links < 3;
  out.push({ json: {
    receivedAt: new Date().toISOString(), name: name || 'there', email, phone, message,
    source: pick('source') || 'website form', valid,
    rejectReason: valid ? '' : (!emailOk ? 'invalid email' : honeypot ? 'honeypot filled' : links >= 3 ? 'too many links' : 'message too short'),
  }});
}
return out;

// Read the AI's JSON safely; fall back to a polite holding reply if anything is off.
const s = $('Settings').first().json;
const lead = $('Is Valid?').first().json;
let ai = {};
try {
  const content = $json.choices?.[0]?.message?.content ?? '{}';
  ai = JSON.parse(content.replace(/^```(json)?|```$/g, '').trim());
} catch (e) { ai = {}; }
const allowed = ['booking','question','pricing','complaint','urgent','spam','other'];
const category = allowed.includes(ai.category) ? ai.category : 'other';
const urgent = ai.urgent === true || category === 'urgent';
const fallback = `Hi ${lead.name},\n\nThanks for getting in touch with ${s.businessName}. A member of our team will reply within ${s.responseTime}.\n\n${s.signature}`;
const reply = (typeof ai.reply === 'string' && ai.reply.trim().length > 20) ? ai.reply.trim() : fallback;
return [{ json: {
  ...lead, category, urgent,
  summary: String(ai.summary || lead.message.slice(0, 140)),
  reply: category === 'spam' ? '' : reply,
  aiOk: Object.keys(ai).length > 0,
}}];

// Strip identifiers before anything leaves for the AI provider.
// The full details stay inside n8n for the email reply.
const rules = [
  // DOB: 14/03/1986, 14-3-86, 1986-03-14, 14 March 1986, March 14th, 1986
  [/\b(?:DOB|D\.O\.B\.?|date of birth|born(?: on)?)\s*:?\s*(?:\d{4}[\/.-]\d{1,2}[\/.-]\d{1,2}|\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}|\d{1,2}(?:st|nd|rd|th)?\s+[A-Za-z]{3,9}\.?,?\s+\d{2,4}|[A-Za-z]{3,9}\.?\s+\d{1,2}(?:st|nd|rd|th)?,?\s+\d{2,4})/gi, '[DOB removed]'],
  // NHS number: 10 digits, often 3-3-4
  [/\b[1-9]\d{2}[\s-]?\d{3}[\s-]?\d{4}\b/g, '[NHS no. removed]'],
  // UK postcode
  [/\b[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}\b/gi, '[postcode removed]'],
  // UK phone numbers, mobile or landline, any spacing: 07700 900 123, 020 7946 0958, (020) 7946 0958, +44 7700 900123
  [/(?:\+44\s?\(?0?\)?\s?|\(?\b0)\d(?:[\s-]?\)?[\s-]?\d){8,9}\b/g, '[phone removed]'],
  // Email
  [/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email removed]'],
];
return $input.all().map(item => {
  let msg = item.json.message || '';
  let removed = 0;
  const full = String(item.json.name || '').trim();
  if (full.includes(' ')) msg = msg.split(full).join(full.split(' ')[0]);
  for (const [re, tag] of rules) msg = msg.replace(re, () => { removed++; return tag; });
  const first = String(item.json.name || '').split(' ')[0];
  return { json: { name: first, email: '[not sent to AI]', phone: '[not sent to AI]', message: msg, removed } };
});
